'use strict';
// Estilo y logo tomados literalmente del HTML aprobado por Finanfuturo.
// Se incluyen en JavaScript porque el Desplegador V3.5 solo empaqueta .js/.json/.txt.
const cssAprobado = "\n    :root {--ink:#202826;--muted:#5f6b67;--subtle:#7e8884;--green:#256446;--line:#d9deda;--paper:#fff;--desk:#ecefed;}\n    *{box-sizing:border-box}\n    body{margin:0;background:var(--desk);font-family:Arial,Helvetica,sans-serif;color:var(--ink);-webkit-font-smoothing:antialiased}\n    .tools{height:60px;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:16px;padding:0 max(24px,calc((100vw - 810px)/2));}\n    .tools .tools-name{font-size:13px;font-weight:700;color:#33413b}\n    .tools .tools-sub{font-size:11px;color:var(--muted);margin-top:3px}\n    .tools button{border:1px solid var(--green);color:var(--green);background:white;font-size:12px;font-weight:700;padding:10px 14px;border-radius:5px;cursor:pointer;white-space:nowrap}\n    .tools button:hover{background:#f2f7f3}\n    .sheet{width:210mm;min-height:297mm;margin:27px auto 40px;background:var(--paper);box-shadow:0 9px 35px rgba(0,0,0,.085);padding:17mm 19mm 15mm 19mm;display:flex;flex-direction:column}\n    .head{display:flex;align-items:center;justify-content:space-between;gap:30px;min-height:66px}\n    .logo{display:block;width:156px;height:auto;object-fit:contain}\n    .head-right{text-align:right;align-self:center;font-size:10px;line-height:1.55;color:#515d57;letter-spacing:.08em;text-transform:uppercase}\n    .head-right strong{display:block;color:var(--green);font-size:11px;letter-spacing:.12em}\n    .accent{border:0;border-top:2px solid var(--green);margin:13px 0 27px}\n    .eyebrow{font-size:10px;letter-spacing:.12em;color:var(--green);font-weight:700;text-transform:uppercase}\n    h1{font-size:28px;letter-spacing:-.75px;font-weight:700;margin:9px 0 8px;line-height:1.13}\n    .subtitle{font-size:12.5px;color:var(--muted);line-height:1.5;margin:0 0 25px}\n    .metadata{display:grid;grid-template-columns:1.25fr .75fr .85fr .9fr;column-gap:17px;border-bottom:1px solid var(--line);border-top:1px solid var(--line);padding:16px 0 15px;margin-bottom:27px}\n    .meta-label{display:block;font-size:9px;color:var(--subtle);letter-spacing:.065em;text-transform:uppercase;margin-bottom:6px}\n    .meta-value{font-size:12px;font-weight:700;line-height:1.3}\n    h2{font-size:13.5px;line-height:1.3;margin:0 0 11px;font-weight:700;color:#27342e}\n    .section{margin-bottom:24px}\n    p{font-size:12px;line-height:1.67;margin:0;color:#424b46}\n    .overview{display:flex;justify-content:space-between;gap:25px;align-items:flex-start;margin-bottom:30px}\n    .overview .copy{flex:1;max-width:350px}\n    .amount{flex:none;text-align:right;padding-top:2px;min-width:166px}\n    .amount .title{font-size:10px;color:var(--muted);margin:0 0 9px}\n    .amount .value{font-size:24px;color:var(--green);font-weight:700;white-space:nowrap;letter-spacing:-.6px}\n    .amount .desc{font-size:10px;color:var(--muted);margin-top:8px}\n    .mini-rule{height:1px;background:var(--line);margin:14px 0 22px}\n    table{width:100%;border-collapse:collapse;table-layout:fixed;margin-top:13px;font-size:11.5px}\n    th{text-align:left;font-size:10px;color:#56605b;font-weight:700;padding:10px 8px 10px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}\n    td{vertical-align:top;padding:14px 8px 16px 0;border-bottom:1px solid var(--line);line-height:1.5}\n    th:last-child,td:last-child{text-align:right;padding-right:0}\n    td strong{font-weight:700}\n    .muted{color:var(--muted)}\n    .small{font-size:10.5px;margin-top:5px;color:var(--muted)}\n    .money{white-space:nowrap;font-size:11.5px;font-variant-numeric:tabular-nums}\n    .total{display:flex;justify-content:space-between;align-items:center;padding-top:14px;gap:16px;font-size:13px;font-weight:700}\n    .total strong{font-size:16px;color:var(--green);font-variant-numeric:tabular-nums}\n    .twocol{display:grid;grid-template-columns:1fr 1fr;gap:30px;margin-top:2px}\n    .twocol .section{margin:0}\n    .twocol h2{margin-bottom:10px}\n    .twocol p{font-size:11.5px;line-height:1.65}\n    .twocol p+p{margin-top:9px}\n    .label-inline{font-weight:700;color:#28362e}\n    .next{border-top:1px solid var(--line);margin-top:25px;padding-top:18px}\n    .next p{font-size:11.5px}\n    .foot{margin-top:auto;border-top:1px solid var(--line);padding-top:11px;display:flex;align-items:flex-end;justify-content:space-between;gap:20px;font-size:9px;color:#7d8580;line-height:1.5}\n    .foot strong{font-size:9px;display:block;color:#4d5951;letter-spacing:.04em}\n    .foot .right{text-align:right;white-space:nowrap}\n    @media(max-width:850px){.tools{padding:12px 20px}.sheet{width:min(100%,760px);min-height:auto;margin:14px auto;padding:38px 35px}.amount .value{font-size:22px}}\n    @media(max-width:560px){.tools{height:auto;align-items:flex-start}.tools .tools-sub{font-size:10px}.sheet{padding:28px 18px}.logo{width:116px}.head-right{font-size:8px}.metadata{grid-template-columns:1fr 1fr;row-gap:16px}.overview{flex-direction:column;gap:14px}.amount{text-align:left}.twocol{grid-template-columns:1fr;gap:18px}h1{font-size:23px}table{font-size:10px}th{font-size:9px}.money{white-space:normal}}\n    @page{size:A4;margin:0}\n    @media print{body{background:white}.tools{display:none}.sheet{margin:0;box-shadow:none;border:none;width:210mm;min-height:297mm;padding:17mm 19mm 15mm 19mm;print-color-adjust:exact;-webkit-print-color-adjust:exact}.twocol{grid-template-columns:1fr 1fr;gap:30px}.overview{flex-direction:row}.amount{text-align:right}h1{font-size:28px}.metadata{grid-template-columns:1.25fr .75fr .85fr .9fr}table{font-size:11.5px}th{font-size:10px}.money{white-space:nowrap}.section,table,.overview,.twocol,.next{break-inside:avoid}}\n  \n/* Print: preserve the approved visual language on each A4 page. */\n@page { size: A4; margin: 17mm 19mm 22mm 19mm; }\n@media print {\n  body { margin: 0; background: #fff; }\n  .sheet { display: block !important; width: auto !important; min-height: 0 !important;\n    margin: 0 !important; padding: 0 !important; box-shadow: none !important; }\n  .foot, .tools { display: none !important; }\n  .section, .overview, .twocol, .next { break-inside: auto !important; }\n  .metadata, .head, .overview, .twocol, .total { break-inside: avoid !important; }\n  table { break-inside: auto !important; table-layout: fixed; }\n  thead { display: table-header-group; }\n  tr { break-inside: avoid; }\n  th, td { overflow-wrap: anywhere; word-break: normal; }\n  .money { white-space: normal; }\n  .next { margin-top: 16px; }\n  .head { min-height: 58px; }\n}\n";
const logoDataUri = "data:image/png;base64,";
module.exports={cssAprobado,logoDataUri};
